import json, subprocess, sys
REPO="G-ACE-inc/server-core"
EXPECTED="7648bd2da2e30fc985139d635ef4eba4b7e6848c"
def gh(method,path,data=None):
    args=["gh","api", "-X",method,"repos/"+REPO+"/"+path]
    if data is not None:
        args += ["--input","-"]
    p=subprocess.run(args,input=json.dumps(data) if data is not None else None,
                     capture_output=True,text=True,timeout=45)
    if p.returncode:
        raise RuntimeError("GITHUB_"+path.split("/")[0]+"_"+str(p.returncode))
    return json.loads(p.stdout) if p.stdout.strip() else {}
try:
    pr=gh("GET","pulls/299")
    branch=gh("GET","branches/main")
    head=pr.get("head",{}).get("sha")
    if head != EXPECTED or pr.get("state")!="open" or pr.get("draft") is not True:
        raise RuntimeError("PR_HEAD_OR_STATE_CHANGED")
    result=gh("POST","merges",{
        "base":"main","head":"agent-pool/review-provenance-20261016",
        "commit_message":"Agent Pool CU40: merge validated PR299 implementation without enabling Codex auto-review"
    })
    new=gh("GET","branches/main")
    print("AGENT_POOL_MAIN_MERGE="+json.dumps({
        "pr":299,"old_main":branch.get("commit",{}).get("sha"),
        "new_main":new.get("commit",{}).get("sha"),
        "merge_sha":result.get("sha"),"pr_head":head,
        "merge_operation":"github_authenticated_merges_api",
        "ready_review_transition":False
    },sort_keys=True))
except Exception as exc:
    print("AGENT_POOL_MAIN_MERGE_FAILED="+str(exc)[:100])
    sys.exit(1)
PY
